<?php require_once __DIR__.'/includes/bootstrap.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$type=$_POST['type']??'';$action=$_POST['action']??'';if($type==='shop'&&in_array($action,['approved','suspended'],true))$pdo->prepare('UPDATE shops SET status=? WHERE id=?')->execute([$action,$id]);if($type==='product'&&in_array($action,['active','rejected'],true))$pdo->prepare('UPDATE products SET status=? WHERE id=?')->execute([$action,$id]);flash('Admin action completed.');header('Location: admin.php');exit;}$shops=$pdo->query('SELECT s.*,u.name,u.email FROM shops s JOIN users u ON u.id=s.user_id ORDER BY s.created_at DESC')->fetchAll();$products=$pdo->query('SELECT p.*,s.shop_name FROM products p JOIN shops s ON s.id=p.shop_id ORDER BY p.created_at DESC')->fetchAll();$users=$pdo->query('SELECT COUNT(*) n FROM users')->fetch()['n'];$orders=$pdo->query('SELECT COUNT(*) n FROM orders')->fetch()['n'];require 'includes/header.php';?><div class="section-head"><h1>Administrator dashboard</h1></div><div class="stats"><div class="stat"><span class="muted">Users</span><strong><?=$users?></strong></div><div class="stat"><span class="muted">Orders</span><strong><?=$orders?></strong></div><div class="stat"><span class="muted">Shops</span><strong><?=count($shops)?></strong></div></div><section class="panel"><h2>Seller applications</h2><div class="table-wrap"><table><tr><th>Shop</th><th>Owner</th><th>Location</th><th>Status</th><th>Action</th></tr><?php foreach($shops as $s):?><tr><td><?=e($s['shop_name'])?></td><td><?=e($s['name'])?><br><?=e($s['email'])?></td><td><?=e($s['location'])?></td><td><?=e($s['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$s['id']?>"><input type="hidden" name="type" value="shop"><button name="action" value="approved">Approve</button> <button class="btn secondary" name="action" value="suspended">Suspend</button></form></td></tr><?php endforeach;?></table></div></section><section class="panel"><h2>Product moderation</h2><div class="table-wrap"><table><tr><th>Product</th><th>Shop</th><th>Price</th><th>Status</th><th>Action</th></tr><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['shop_name'])?></td><td><?=money($p['price'])?></td><td><?=e($p['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="type" value="product"><button name="action" value="active">Approve</button> <button class="btn secondary" name="action" value="rejected">Reject</button></form></td></tr><?php endforeach;?></table></div></section><?php require 'includes/footer.php';?>
